css:
a { text-decoration: none; }
p { margin: 0; }
h1, h2, h3 { margin: 0; padding: 0; }
:root { color-scheme: light only; }
@media only screen and (max-width: 580px) {
  .th-it-text > table > tbody > tr > td { padding-top: 0 !important; }
  .th-center-mobile div, .th-center-mobile p, .th-center-mobile h2 { text-align: center !important; }
  .th-product-name div { font-size: 13px !important; line-height: 19px !important; }
  .th-headline h2 { font-size: 18px !important; line-height: 25px !important; }
  .th-hide-mobile { display: none !important; }
}
